#include <stdio.h>
/* ex10：集线器 vs 交换机 —— 物理层设备与链路层设备的本质差别
 * 集线器（Hub，物理层）：所有端口在同一个「冲突域」和同一个「广播域」，
 *   总带宽被所有主机共享，且同一时刻只能有一台发（CSMA/CD 仲裁）。
 * 交换机（Switch，链路层）：每个端口是独立的冲突域，
 *   全双工下每口独享带宽，靠 MAC 地址表转发。
 * 这个差别直接决定「10 台机器接 hub 还是接 switch」的性能差 10 倍。*/
int main(void) {
    int hosts = 10;
    double port_mbps = 100.0;

    printf("%d 台主机，每台网卡 100Mbps\n", hosts);
    printf("--------------------------------------------------------------\n");
    printf("%-18s %-16s %-18s %s\n", "设备", "冲突域", "每主机可用带宽", "同时发送");
    printf("%-18s %-16s %-18.1f %s\n", "集线器 Hub", "1 个（共享）",
           port_mbps / hosts, "不能（CSMA/CD 竞争）");
    printf("%-18s %-16s %-18.1f %s\n", "交换机 Switch", "10 个（每口一个）",
           port_mbps, "能（全双工）");
    printf("--------------------------------------------------------------\n");
    printf("带宽差距 = %d 倍\n", hosts);
    printf("\n补充要点（408 常考）：\n");
    printf("  1) 集线器工作在物理层，只做「信号放大整形转发」，不看 MAC 地址；\n");
    printf("     所以它天然属于「冲突域设备」，也是为什么 hub 级联会放大冲突。\n");
    printf("  2) 交换机分割「冲突域」但不分割「广播域」—— 广播帧仍会泛洪到所有端口；\n");
    printf("     要分割广播域必须用路由器或 VLAN。\n");
    printf("  3) 中继器（Repeater）与 hub 同为物理层设备，区别只是端口数；\n");
    printf("     两者都会「放大噪声」，且不能连接不同速率的网段（hub 例外，可自适应）。\n");
    return 0;
}
